<script setup lang="ts">
import {questionOptions} from '../../../../packages/shared/src/questionOptions';
import {ref,onMounted,onBeforeUnmount} from 'vue';import {get} from '../../../../packages/shared/src/client';import {enrolledCourseOptions} from '../../../../packages/shared/src/courseOptions';import {useOperations} from '../../../../packages/shared/src/operations';import {useTask,query,type Row} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const task=useTask(),ops=useOperations(),rows=ref<Row[]>([]),total=ref(0),page=ref(1),courseId=ref(''),type=ref(''),mastered=ref('false'),courses=ref<Row[]>([]),selected=ref<Row>(),response=ref(''),result=ref<Row>();
const listBusy=ref(false),listError=ref('');let listRevision=0;
const isMastered=(value:unknown)=>value===true||value===1||value==='1';
async function load(){
 const revision=++listRevision,requested={pageNo:page.value,pageSize:20,courseId:courseId.value,type:type.value,mastered:mastered.value};listBusy.value=true;listError.value='';
 try{let result=await get<Row>('/exam-review/page?'+query(requested));if(revision!==listRevision)return;
  const lastPage=Math.max(1,Math.ceil(Number(result.total||0)/20));if(requested.pageNo>lastPage){requested.pageNo=lastPage;page.value=lastPage;result=await get<Row>('/exam-review/page?'+query(requested));if(revision!==listRevision)return;}
  rows.value=result.list||[];total.value=Number(result.total||0);
 }catch(error){if(revision===listRevision){rows.value=[];total.value=0;listError.value=error instanceof Error?error.message:'错题加载失败';}}finally{if(revision===listRevision)listBusy.value=false;}
}
async function open(row:Row){await task.run(async()=>{selected.value=await loadQuestion(row);response.value='';result.value=undefined;});}
async function review(){await task.run(async()=>{const row=selected.value!;const op=await ops.begin('exam','错题复习','/exam-review/'+row.attempt_id+'/'+row.question_id+'/reviews',{response:response.value,version:row.version});if(op.status==='SUCCEEDED'){selected.value=await loadQuestion(row);result.value=selected.value;task.message.value='复习已记录，原考试成绩保持不变';}});}
async function mark(){const ok=await task.run(async()=>{const row=selected.value!;const op=await ops.begin('exam','更新掌握状态','/exam-review/'+row.attempt_id+'/'+row.question_id+'/state',{mastered:!isMastered(row.mastered),version:row.version},'PUT');return op.status==='SUCCEEDED';});if(ok){selected.value=undefined;await load();}}
const choicesAbort=new AbortController();onBeforeUnmount(()=>{listRevision++;choicesAbort.abort();});
onMounted(async()=>{await load();if(choicesAbort.signal.aborted)return;await task.run(async()=>{try{const all=await enrolledCourseOptions(choicesAbort.signal);if(!choicesAbort.signal.aborted)courses.value=all;}catch(error){if(!choicesAbort.signal.aborted)throw error;}});});
async function loadQuestion(row:Row){const detail=await get<Row>('/exam-review/'+row.attempt_id+'/'+row.question_id);detail.options=questionOptions(detail.options);return detail;}
</script><template><section class="card review-page"><div class="section-heading"><div><h1>错题复习</h1><p>回到失分的地方，把理解再向前推进一步。</p></div><RouterLink to="/exams">考试记录 →</RouterLink></div><Status :busy="task.busy.value||listBusy" :error="task.error.value||listError" :message="task.message.value"/><el-button v-if="listError" @click="load" :disabled="listBusy">重试加载错题</el-button><div class="toolbar"><el-select v-model="courseId" clearable aria-label="筛选错题课程" placeholder="全部课程" @change="page=1;load()"><el-option v-for="c in courses" :key="c.courseId" :value="String(c.courseId)" :label="c.courseName"/></el-select><el-select v-model="type" clearable aria-label="筛选题型" placeholder="全部题型" @change="page=1;load()"><el-option v-for="(name,i) in ['单选题','多选题','不定项选择','判断题','主观题']" :key="name" :label="name" :value="String(i+1)"/></el-select><el-select v-model="mastered" aria-label="掌握状态" @change="page=1;load()"><el-option label="待复习" value="false"/><el-option label="已掌握" value="true"/><el-option label="全部" value=""/></el-select></div><article v-for="row in rows" :key="row.attempt_id+'-'+row.question_id" class="review-row"><div><h3>{{row.name}}</h3><p>原考试得分 {{row.score}} / {{row.max_score}} · {{isMastered(row.mastered)?'已掌握':'待复习'}}</p></div><el-button @click="open(row)">复习这道题</el-button></article><el-empty v-if="!rows.length&&!task.busy.value&&!listBusy&&!task.error.value&&!listError" description="当前筛选下没有错题"/><el-pagination v-if="total>20||page>1" v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/><el-dialog :model-value="!!selected" title="复习错题" @update:model-value="(v:boolean)=>{if(!v)selected=undefined;}"><template v-if="selected"><h3>{{selected.name}}</h3><p v-for="(option,i) in selected.options" :key="i">{{String.fromCharCode(65+Number(i))}}. {{option}}</p><el-input v-model="response" type="textarea" :rows="4" placeholder="写下你的答案；选择题填写选项编号，多选用逗号分隔" aria-label="复习答案"/><el-button type="primary" @click="review" :disabled="!response.trim()||task.busy.value">提交复习</el-button><p v-if="result?.reviews?.length" class="answer-feedback" role="status">{{result.reviews[0].correct==null?'主观题请对照解析与教师反馈复盘':Number(result.reviews[0].correct)===1?'本次回答正确':'本次回答仍有误，请对照解析再想一想'}}</p><details v-if="selected.reviews?.length" class="review-explanation"><summary>最近练习记录</summary><article v-for="item in selected.reviews" :key="item.id"><p>{{item.response}}</p><small>{{item.created_at}} · {{item.correct==null?'主观题自行对照':Number(item.correct)===1?'回答正确':'回答有误'}}</small></article></details><details class="review-explanation" :open="!!result"><summary>查看标准答案与解析</summary><p>标准答案：{{selected.answer}}</p><p>解析：{{selected.analysis||'暂无解析'}}</p><p v-if="selected.feedback">教师反馈：{{selected.feedback}}</p></details><p class="muted">复习仅记录掌握情况，不修改原考试成绩。</p><el-button @click="mark" :disabled="task.busy.value">{{isMastered(selected.mastered)?'重新加入复习':'标记已掌握'}}</el-button></template><Status :busy="task.busy.value" :error="task.error.value"/></el-dialog></section></template>